        a=min(r for r,x in cells); b=max(r for r,x in cells); l=min(x for r,x in cells); q=max(x for r,x in cells)
        if b-a>=2 and q-l>=2 and all(g[r][x]==c for r in (a,b) for x in range(l,q+1)) and all(g[r][x]==c for r in range(a,b+1) for x in (l,q)):
            p=[[g[r][x] for x in range(l+1,q)] for r in range(a+1,b)]
